// Build the AI Agent prompt based on the current execution mode
const mergeData = $input.first().json;
const triggerData = $('🔀 Merge – Triggers').first().json;
const mode = triggerData.mode ?? 'launch';

let prompt = '';

if (mode === 'launch') {
  const campaignId   = triggerData.campaign_id ?? 'UNKNOWN';
  const assets       = triggerData.approved_assets ?? [];
  const strategy     = triggerData.campaign_strategy ?? {};
  const budgets      = triggerData.channel_budgets ?? {};

  prompt = `You are operating in **LAUNCH MODE**.

## LAUNCH MODE

You have received approved production assets from upstream agents. Build a full channel execution plan.

**Campaign ID:** ${campaignId}

**Approved Assets:**
${JSON.stringify(assets, null, 2)}

**Campaign Strategy:**
${JSON.stringify(strategy, null, 2)}

**Channel Budgets:**
${JSON.stringify(budgets, null, 2)}

Produce a JSON launch plan in exactly this format:
{
  "mode": "launch",
  "campaign_id": "string",
  "channel_plans": [{
    "channel": "paid_social | paid_search | email | seo | social_organic | video",
    "agent": "ppc | email | seo | social | google | video",
    "assets": ["array of asset IDs"],
    "audience_targeting": "string",
    "budget": "string",
    "objective": "string",
    "kpi": "string",
    "launch_date": "string"
  }],
  "test_framework": [{ "variable": "string", "hypothesis": "string", "metric": "string", "minimum_sample": "string" }],
  "tracking": { "utm_structure": "string", "conversion_events": ["array"], "attribution_model": "string" },
  "status": "launch_plan_complete"
}`;

} else {
  const ga4Data      = mergeData.ga4       ?? {};
  const googleAds    = mergeData.google_ads ?? {};
  const metaAds      = mergeData.meta_ads  ?? {};
  const hubspot      = mergeData.hubspot   ?? {};
  const airtable     = mergeData.airtable  ?? {};

  prompt = `You are operating in **OPTIMIZE MODE**.

## OPTIMIZE MODE

You have received aggregated performance data from all active channels. Analyse it and produce optimization signals.

**GA4 Data:**
${JSON.stringify(ga4Data, null, 2)}

**Google Ads Data:**
${JSON.stringify(googleAds, null, 2)}

**Meta Ads Data:**
${JSON.stringify(metaAds, null, 2)}

**HubSpot Email Data:**
${JSON.stringify(hubspot, null, 2)}

**Airtable Records:**
${JSON.stringify(airtable, null, 2)}

Produce a JSON optimization plan in exactly this format:
{
  "mode": "optimize",
  "performance_summary": { "overall_vs_kpi": "string", "top_performer": "string", "underperformer": "string" },
  "optimization_actions": [{ "channel": "string", "action": "string", "rationale": "string", "data_point": "string" }],
  "signals_to_agents": {
    "to_creative_director": "string | null",
    "to_content_manager": "string | null",
    "to_ppc": "string | null",
    "to_email": "string | null",
    "to_social": "string | null"
  },
  "creative_refresh_required": true,
  "strategy_loop_back": "string | null",
  "status": "optimization_complete"
}`;
}

return [{ json: { prompt, mode } }];

// Parse the AI agent's JSON output
const raw = $input.first().json.output;
let parsed;
try {
  // Strip markdown code fences if present
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { mode: 'unknown', error: 'Failed to parse AI output', raw };
}

return [{ json: parsed }];

